export const BLOOM_THRESHOLD_FRAG = `#version 300 es
precision highp float;

uniform sampler2D uTex;
uniform float uThreshold;
in vec2 vUv;
out vec4 fragColor;

void main(){
  vec4 c = texture(uTex, vUv);
  float lum = dot(c.rgb, vec3(0.299, 0.587, 0.114));
  float knee = 0.08;
