    ember: [0.16, 0.5, 1.0],
    hot: [0.78, 0.93, 1.0],
    gA: [0.04, 0.2, 0.9],
    gB: [0.3, 0.68, 1.0],
  },
  neon: {
    ash: [0.64, 0.57, 0.72],
    ember: [1.0, 0.17, 0.84],
    hot: [0.36, 0.95, 1.0],
